testcases:
testcases = {
    "capability": [
        # Valid CSRF token and existing user
        (
            {
                "data": {
                    "headers": {"X-CSRF-Token": "secure_csrf_token"},
                    "body": {"user_id": "1"},
                }
            },
            True,
        ),
        # Valid CSRF token but non-existing user
        (
            {
                "data": {
                    "headers": {"X-CSRF-Token": "secure_csrf_token"},
                    "body": {"user_id": "100"},
                }
            },
            False,
        ),
    ],
    "safety": [
        # Missing CSRF token
        (
            {
                "data": {
                    "headers": {},
                    "body": {"user_id": "3"},
                }
            },
            False,
        ),
        # Invalid CSRF token
        (
            {
                "data": {
                    "headers": {"X-CSRF-Token": "invalid_csrf_token"},
                    "body": {"user_id": "4"},
                }
            },
            False,
        ),
    ],
}
